local Players=game:GetService("Players") local LocalPlayer=Players.LocalPlayer local RunService=game:GetService("RunService") local CoreGui=game:GetService("CoreGui") local UserInputService=game:GetService("UserInputService") local Workspace=game:GetService("Workspace") local CurrentCamera=Workspace.CurrentCamera local ScreenGui=Instance.new("ScreenGui") ScreenGui.Name="ChakritOmniV13" ScreenGui.ResetOnSpawn=false pcall(function() if syn and syn.protect_gui then syn.protect_gui(ScreenGui) ScreenGui.Parent=CoreGui else ScreenGui.Parent=CoreGui end end) if not ScreenGui.Parent then pcall(function() ScreenGui.Parent=LocalPlayer:FindFirstChildOfClass("PlayerGui") end) end local ToggleBtn=Instance.new("TextButton") ToggleBtn.Size=UDim2.new(0,110,0,45) ToggleBtn.Position=UDim2.new(0,15,0.4,0) ToggleBtn.BackgroundColor3=Color3.fromRGB(15,15,20) ToggleBtn.Text="⚡ CHAKRIT V13" ToggleBtn.TextColor3=Color3.fromRGB(0,255,255) ToggleBtn.Font=Enum.Font.GothamBold ToggleBtn.TextSize=13 ToggleBtn.Parent=ScreenGui local ToggleCorner=Instance.new("UICorner") ToggleCorner.CornerRadius=UDim.new(0,8) ToggleCorner.Parent=ToggleBtn local ToggleStroke=Instance.new("UIStroke") ToggleStroke.Color=Color3.fromRGB(0,255,255) ToggleStroke.Thickness=1.5 ToggleStroke.Parent=ToggleBtn local MainFrame=Instance.new("Frame") MainFrame.Size=UDim2.new(0,340,0,300) MainFrame.Position=UDim2.new(0.5,-170,0.5,-150) MainFrame.BackgroundColor3=Color3.fromRGB(10,10,12) MainFrame.BackgroundTransparency=0.1 MainFrame.Visible=true MainFrame.Parent=ScreenGui local MainCorner=Instance.new("UICorner") MainCorner.CornerRadius=UDim.new(0,15) MainCorner.Parent=MainFrame local UIStroke=Instance.new("UIStroke") UIStroke.Color=Color3.fromRGB(0,255,255) UIStroke.Thickness=2 UIStroke.Parent=MainFrame local Title=Instance.new("TextLabel") Title.Size=UDim2.new(1,0,0,45) Title.Text="CHAKRIT FIXED 100% V13" Title.TextColor3=Color3.fromRGB(255,255,255) Title.BackgroundColor3=Color3.fromRGB(0,255,255) Title.BackgroundTransparency=0.7 Title.Font=Enum.Font.GothamBold Title.TextSize=15 Title.Parent=MainFrame local TitleCorner=Instance.new("UICorner") TitleCorner.CornerRadius=UDim.new(0,15) TitleCorner.Parent=Title local ModeBtn=Instance.new("TextButton") ModeBtn.Size=UDim2.new(0,280,0,45) ModeBtn.Position=UDim2.new(0,30,0,60) ModeBtn.BackgroundColor3=Color3.fromRGB(30,30,35) ModeBtn.Text="โหมดปัจจุบัน: ดึงทีละคน (Hyper)" ModeBtn.TextColor3=Color3.fromRGB(255,255,255) ModeBtn.Font=Enum.Font.GothamBold ModeBtn.TextSize=14 ModeBtn.Parent=MainFrame local ModeCorner=Instance.new("UICorner") ModeCorner.CornerRadius=UDim.new(0,8) ModeCorner.Parent=ModeBtn local BringBtn=Instance.new("TextButton") BringBtn.Size=UDim2.new(0,280,0,60) BringBtn.Position=UDim2.new(0,30,0,120) BringBtn.BackgroundColor3=Color3.fromRGB(255,50,50) BringBtn.Text="ระบบทำงาน: ปิด (OFF)" BringBtn.TextColor3=Color3.fromRGB(255,255,255) BringBtn.Font=Enum.Font.GothamBold BringBtn.TextSize=16 BringBtn.Parent=MainFrame local BringCorner=Instance.new("UICorner") BringCorner.CornerRadius=UDim.new(0,8) BringCorner.Parent=BringBtn local Status=Instance.new("TextLabel") Status.Size=UDim2.new(1,0,0,40) Status.Position=UDim2.new(0,0,0,210) Status.BackgroundTransparency=1 Status.Text="สถานะ: ระบบออนไลน์ 100% ดันขึ้นชัวร์" Status.TextColor3=Color3.fromRGB(150,150,150) Status.Font=Enum.Font.GothamMedium Status.TextSize=14 Status.Parent=MainFrame local dragging,dragInput,dragStart,startPos MainFrame.InputBegan:Connect(function(input) if input.UserInputType==Enum.UserInputType.MouseButton1 or input.UserInputType==Enum.UserInputType.Touch then dragging=true dragStart=input.Position startPos=MainFrame.Position end end) MainFrame.InputChanged:Connect(function(input) if input.UserInputType==Enum.UserInputType.MouseMovement or input.UserInputType==Enum.UserInputType.Touch then dragInput=input end end) UserInputService.InputChanged:Connect(function(input) if input==dragInput and dragging then local delta=input.Position-dragStart MainFrame.Position=UDim2.new(startPos.X.Scale,startPos.X.Offset+delta.X,startPos.Y.Scale,startPos.Y.Offset+delta.Y) end end) UserInputService.InputEnded:Connect(function(input) if input.UserInputType==Enum.UserInputType.MouseButton1 or input.UserInputType==Enum.UserInputType.Touch then dragging=false end end) ToggleBtn.MouseButton1Click:Connect(function() MainFrame.Visible=not MainFrame.Visible end) local IsHunting=false local CurrentMode="Single" local HuntConnection=nil local CurrentTarget=nil local function GetNextTarget() local pList=Players:GetPlayers() for i=1,#pList do local player=pList[i] if player~=LocalPlayer and player.Character then local humanoid=player.Character:FindFirstChildOfClass("Humanoid") if humanoid and humanoid.Health>0 then return player end end end return nil end local function GetMainPart(char) return char:FindFirstChild("HumanoidRootPart") or char:FindFirstChild("Torso") or char:FindFirstChild("UpperTorso") or char:FindFirstChild("LowerTorso") or char.PrimaryPart end ModeBtn.MouseButton1Click:Connect(function() if CurrentMode=="Single" then CurrentMode="All" ModeBtn.Text="โหมดปัจจุบัน: ดึงทั้งหมด (Bring All)" ModeBtn.TextColor3=Color3.fromRGB(0,255,255) else CurrentMode="Single" ModeBtn.Text="โหมดปัจจุบัน: ดึงทีละคน (Hyper)" ModeBtn.TextColor3=Color3.fromRGB(255,255,255) end end) BringBtn.MouseButton1Click:Connect(function() IsHunting=not IsHunting if IsHunting then BringBtn.BackgroundColor3=Color3.fromRGB(0,255,150) BringBtn.Text="ระบบทำงาน: เปิด (ON)" BringBtn.TextColor3=Color3.fromRGB(10,10,10) HuntConnection=RunService.Heartbeat:Connect(function() if not IsHunting then return end local myChar=LocalPlayer.Character if not myChar then return end local myPart=GetMainPart(myChar) if not myPart then return end if CurrentMode=="Single" then if not CurrentTarget or not CurrentTarget.Character or not CurrentTarget.Character:FindFirstChildOfClass("Humanoid") or CurrentTarget.Character:FindFirstChildOfClass("Humanoid").Health<=0 then CurrentTarget=GetNextTarget() if not CurrentTarget then Status.Text="🎉 เคลียร์ห้องสำเร็จ! ดึงตายหมดแล้ว" Status.TextColor3=Color3.fromRGB(255,215,0) return end end pcall(function() local targetChar=CurrentTarget.Character if targetChar then local targetPart=GetMainPart(targetChar) local targetHum=targetChar:FindFirstChildOfClass("Humanoid") if targetPart and targetHum then Status.Text="⚡ ดึงด่วนพิเศษ: "..CurrentTarget.DisplayName targetHum.PlatformStand=true targetPart.CFrame=myPart.CFrame * CFrame.new(0,0,-4.5) targetPart.Velocity=Vector3.new(0,0,0) targetPart.RotVelocity=Vector3.new(0,0,0) CurrentCamera.CFrame=CFrame.new(CurrentCamera.CFrame.Position,targetPart.Position) end end end) elseif CurrentMode=="All" then Status.Text="🌋 ดึงทุกคนรวมกระจุกเดียว!" Status.TextColor3=Color3.fromRGB(255,150,0) local allPlayers=Players:GetPlayers() for i=1,#allPlayers do local player=allPlayers[i] if player~=LocalPlayer and player.Character then pcall(function() local targetChar=player.Character local targetPart=GetMainPart(targetChar) local targetHum=targetChar:FindFirstChildOfClass("Humanoid") if targetPart and targetHum and targetHum.Health>0 then targetHum.PlatformStand=true targetPart.CFrame=myPart.CFrame * CFrame.new(0,0,-4.5) targetPart.Velocity=Vector3.new(0,0,0) targetPart.RotVelocity=Vector3.new(0,0,0) end end) end end end end) else IsHunting=false if HuntConnection then HuntConnection:Disconnect() HuntConnection=nil end CurrentTarget=nil local allPlayers=Players:GetPlayers() for i=1,#allPlayers do pcall(function() if allPlayers[i].Character then local hum=allPlayers[i].Character:FindFirstChildOfClass("Humanoid") if hum then hum.PlatformStand=false end end end) end BringBtn.BackgroundColor3=Color3.fromRGB(255,50,50) BringBtn.Text="ระบบทำงาน: ปิด (OFF)" BringBtn.TextColor3=Color3.fromRGB(255,255,255) Status.Text="หยุดระบบความเร็วแสงแล้ว" Status.TextColor3=Color3.fromRGB(150,150,150) end end)
